const tk = ($('AnyAPI: TikTok Top').first().json.output) || {};
const ig = ($('AnyAPI: Instagram Reels').first().json.output) || {};
const tkItems = (tk.data && tk.data.items) || tk.items || [];
const igItems = (ig.data && ig.data.reels) || ig.reels || [];
const rows = [];
for (const v of tkItems) { rows.push({ platform: 'TikTok', author: v.author || '', caption: v.caption || '', url: v.url || '', views: Number(v.views) || 0, likes: Number(v.likes) || 0, comments: Number(v.comments) || 0 }); }
for (const v of igItems) { rows.push({ platform: 'Instagram Reels', author: v.username || '', caption: v.caption || '', url: v.url || '', views: Number(v.views) || Number(v.plays) || 0, likes: Number(v.likes) || 0, comments: Number(v.comments) || 0 }); }
rows.sort(function (a, b) { return b.views - a.views; });
const top = rows.slice(0, 8);
const lines = [];
for (let i = 0; i < top.length; i++) { const v = top[i]; lines.push((i + 1) + '. [' + v.platform + '] @' + v.author + ' - ' + (v.views || 0).toLocaleString() + ' views, ' + (v.likes || 0).toLocaleString() + ' likes\n   Caption: ' + String(v.caption || '').slice(0, 180) + '\n   URL: ' + v.url); }
const niche = $('Set Niche').first().json.niche;
const videosText = lines.join('\n\n');
return [{ json: { niche: niche, generatedAt: $now.toISO(), count: top.length, videos: top, videosText: videosText } }];

